// The UH-60A blade tables in data/uh60a/ (GenHel CR-166309 Tables 1.5.1 to
// 1.5.3, generated by tools/build_uh60a_blade.py) load through the production
// readers, and the merged airfoil grid reproduces GenHel's two-map lookup.

#include <numbers>
#include <string>
#include <vector>

#include <gtest/gtest.h>

#include "rotor/airfoil.hpp"
#include "util/csv_table.hpp"
#include "util/table.hpp"

namespace eyas {
namespace {

constexpr double kDeg = std::numbers::pi / 180.0;
const std::string kVehicleData = EYAS_VEHICLE_DATA_DIR;

Airfoil sc1095() {
    return Airfoil::from_csv(read_csv_table(kVehicleData + "/uh60a/sc1095.csv"));
}

TEST(Uh60aData, Sc1095LoadsAndMatchesTheTablesAtNodes) {
    const Airfoil af = sc1095();
    TableCursor<2> c;
    // Primary map (Table 1.5.2 / 1.5.3, |alpha| <= 32 deg), Mach 0 and 0.9.
    EXPECT_DOUBLE_EQ(af(0.0, 0.0, c).cl, 0.03);
    EXPECT_DOUBLE_EQ(af(12.0 * kDeg, 0.0, c).cl, 1.25);
    EXPECT_DOUBLE_EQ(af(0.0, 0.0, c).cd, 0.0075);
    EXPECT_DOUBLE_EQ(af(0.0, 0.9, c).cd, 0.05);
    // High-angle map, the same at every Mach.
    EXPECT_DOUBLE_EQ(af(90.0 * kDeg, 0.0, c).cl, 0.025);
    EXPECT_DOUBLE_EQ(af(90.0 * kDeg, 1.0, c).cl, 0.025);
    EXPECT_DOUBLE_EQ(af(-86.0 * kDeg, 0.5, c).cd, 2.105);
}

// GenHel looks up the primary map for |alpha| <= 32 deg and the high-angle map
// outside (CR-166309 p. 5.1-4). Every Mach row of the primary map ends on the
// high-angle map's values at 32 deg, so between 32 and 34 deg the merged grid
// interpolates exactly as the high-angle map alone does.
TEST(Uh60aData, MergedGridMatchesTheHighAngleMapAcrossTheJoin) {
    const Airfoil af = sc1095();
    TableCursor<2> c;
    for (const double mach : {0.0, 0.35, 0.7, 1.0}) {
        EXPECT_NEAR(af(33.0 * kDeg, mach, c).cl, 0.5 * (0.9675 + 0.935), 1e-15) << mach;
        EXPECT_NEAR(af(-33.0 * kDeg, mach, c).cd, 0.5 * (0.6975 + 0.765), 1e-15) << mach;
    }
}

TEST(Uh60aData, TwistTableLoads) {
    const CsvTable t = read_csv_table(kVehicleData + "/uh60a/twist.csv");
    const std::vector<double>& r = t.column("r");
    ASSERT_EQ(r.size(), 21U);
    EXPECT_DOUBLE_EQ(r.front(), 0.0);
    EXPECT_DOUBLE_EQ(r.back(), 1.0);
    EXPECT_NEAR(t.column("twist").back(), -10.9 * kDeg, 1e-15);  // converted to rad at load
}

}  // namespace
}  // namespace eyas
